const PROMOTIONS = [
  { productId:'brioche', percent:15, label:'Café da manhã' },
  { productId:'folhas-de-ouro', percent:10, label:'Semana do croissant' },
  { productId:'combo-festa', percent:12, label:'Festa em casa' },
  { productId:'piscina-da-paixao', percent:20, label:'Doce da semana' },
];
const DEMOS = [
  {id:'empresa',name:'Empresa · Aurora Eventos',email:'empresa@demo.maison.test',password:'EmpresaDemo2026',role:'company',branchId:'jardins'},
  {id:'pessoa',name:'Pessoa física · Ana Lima',email:'pessoa@demo.maison.test',password:'PessoaDemo2026',role:'customer',branchId:'pinheiros'},
  {id:'administrador',name:'Administrador de teste',email:'admin@demo.maison.test',password:'AdminDemo2026',role:'admin',branchId:'jardins'},
  {id:'funcionario',name:'Funcionário · Maison Jardins',email:'loja@demo.maison.test',password:'LojaDemo2026',role:'employee',branchId:'jardins'},
];
const REVIEWS = [
  {name:'Mariana C.',rating:5,text:'O bolo personalizado ficou exatamente como eu imaginei. Massa macia e recheio na medida!',date:'2026-10-28'},
  {name:'Rafael T.',rating:5,text:'Os croissants são os melhores da região. Peço toda semana para o café da manhã.',date:'2026-10-21'},
  {name:'Aurora Eventos',rating:4,text:'Combo de festa chegou no horário e agradou todos os convidados. Só faltou mais guardanapos.',date:'2026-10-15'},
  {name:'Juliana P.',rating:5,text:'A Piscina da Paixão é divina. Atendimento muito carinhoso na retirada.',date:'2026-10-09'},
  {name:'Carlos M.',rating:4,text:'Pão de fermentação natural com casca crocante. Voltarei com certeza.',date:'2026-09-30'},
];
const readState = () => { try { return {branchId:'jardins',cart:[],orders:[],...(JSON.parse(localStorage.getItem(STORE_KEY)||'{}'))}; } catch { return {branchId:'jardins',cart:[],orders:[]}; } };
let state = readState();
const persist = () => { try { localStorage.setItem(STORE_KEY,JSON.stringify(state)); } catch { toast('Não foi possível salvar esta demonstração neste navegador.'); } };
const money = amount => new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(amount||0);
const safe = value => String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const branch = () => BRANCHES.find(item=>item.id===state.branchId)||BRANCHES[0];
const qty = () => state.cart.reduce((sum,item)=>sum+Number(item.quantity||0),0);
const subtotal = () => state.cart.reduce((sum,item)=>sum+item.price*item.quantity,0);
const promoFor = id => PROMOTIONS.find(item=>item.productId===id);
const priceWithPromo = product => { const promo=promoFor(product.id);return promo?Math.round(product.price*(100-promo.percent))/100:product.price; };
const demosigned = () => DEMOS.find(item=>item.id===state.demoAccountId)||null;
const stockStatus = id => state.branchStock?.[state.branchId]?.[id] || 'Disponível';
const announce = document.querySelector('#announcements');
function toast(message){ if(!announce)return; announce.textContent=message; announce.classList.add('show'); clearTimeout(toast.timer); toast.timer=setTimeout(()=>announce.classList.remove('show'),3000); }
/* Java coupon lookup is real when the adapter is available; accounts, orders, and other demo data stay local. */
let apiAdapter = window.MaisonApiAdapter || null;
import('./api-client.js').then(module=>{apiAdapter=module.apiClient||module.default||apiAdapter;}).catch(()=>{/* Parent API module is optional. */});
window.MaisonUI = { setApiAdapter(adapter){apiAdapter=adapter;}, getApiAdapter(){return apiAdapter;} };

function currentPath(){const hash=window.location.hash;if(!hash.startsWith('#/'))return '/';return decodeURI(hash.slice(1)).replace(/\/$/,'')||'/';}
function link(path,label,activePath=currentPath()){return `<a href="${path}" class="nav-link ${activePath===path?'active':''}" ${activePath===path?'aria-current="page"':''}>${label}</a>`;}
function header(){return `<div class="topline"><span>✳ &nbsp; Feito à mão. Todos os dias. Especialmente para você. &nbsp; ✳</span></div>
  <header class="site-header"><div class="header-main wrap"><a class="wordmark" href="/" aria-label="Maison, página inicial">maison<span>.</span><small>PADARIA &amp; DOCERIA</small></a>
  <nav class="desktop-nav" aria-label="Navegação principal">${link('/','Nossa vitrine')}${link('/montar-bolo','Monte seu bolo')}${link('/promocoes','Promoções')}${link('/avaliacoes','Avaliações')}</nav>
  <div class="header-actions"><button class="branch-button" type="button" data-action="branch"><span class="pin">⌖</span><span><small>Sua loja</small><strong>${safe(branch().name)}</strong></span><span class="chevron">⌄</span></button><a href="/carrinho" class="bag-link" aria-label="Carrinho, ${qty()} itens"><span aria-hidden="true">♧</span><b>${qty()}</b></a><button class="menu-toggle" data-action="menu" aria-label="Abrir navegação" aria-expanded="false">☰</button></div></div>
  <nav class="mobile-nav wrap" aria-label="Navegação principal">${link('/','Vitrine')}${link('/montar-bolo','Monte seu bolo')}${link('/promocoes','Promoções')}${link('/avaliacoes','Avaliações')}</nav></header>`;}
function footer(){return `<p class="image-note wrap">* Imagens meramente ilustrativas.</p><footer class="footer"><div class="wrap footer-inner"><div><div class="footer-logo">maison.</div><p>Pequenos momentos. Grandes sabores.</p></div><p>© ${new Date().getFullYear()} Maison · Loja demonstrativa · Sem cobranças reais</p><span>♡ &nbsp; Feito com carinho, em São Paulo</span></div></footer>
  <div class="floating-actions"><a href="${demosigned()?'/conta':'/auth'}" aria-label="${demosigned()?'Minha conta':'Entrar'}" title="${demosigned()?'Minha conta':'Entrar'}">♙</a><a class="primary-float" href="${demosigned()?'/atendimento':'/auth'}" aria-label="Atendimento" title="Atendimento">☏</a></div>`;}
function shell(content){return `${header()}${state.demoAccountId?`<div class="demo-strip"><div class="wrap">Demonstração isolada · ${safe(demosigned()?.name||'perfil de teste')} <a href="/testes">Painel de testes →</a></div></div>`:''}${content}${footer()}<dialog id="branch-dialog" class="dialog branch-dialog"><form method="dialog"><button class="dialog-close" aria-label="Fechar">×</button></form><span class="eyebrow center">MAISON, PERTINHO DE VOCÊ</span><h2 class="serif center">Sua Maison, pertinho de você.</h2><p class="muted center">Escolha uma loja para preparar o seu pedido.</p><div class="branch-options">${BRANCHES.map(item=>`<button data-action="choose-branch" data-id="${item.id}" class="branch-option"><span>⌖</span><span><strong>Maison ${item.name}</strong><small>${item.address}</small></span>${state.branchId===item.id?'✓':'→'}</button>`).join('')}</div><p class="tiny center muted">Endereços de exemplo para esta demonstração.</p></dialog>`;}
function badge(tag){return tag?`<span class="product-tag">✦ ${safe(tag)}</span>`:'';}
function productCard(product,{promo=false}={}){const activePromo=promoFor(product.id);const current=priceWithPromo(product);const stock=stockStatus(product.id);const available=stock==='Disponível';return `<article class="product-card"><div class="product-photo"><img src="${product.image}" alt="${safe(product.name)}" loading="lazy">${promo?`<span class="discount">−${activePromo?.percent||0}%</span>`:badge(product.tag)}</div><div class="product-info"><p class="product-meta">${product.category} · Produção artesanal</p><h3>${safe(product.name)}</h3><p class="product-desc">${safe(product.description)}</p><div class="product-bottom"><span>${promo||activePromo?`<s>${money(product.price)}</s> `:''}<strong>${money(current)}</strong></span><button class="add-button" data-action="add" data-id="${product.id}" aria-label="Adicionar ${safe(product.name)} ao carrinho" ${available?'':'disabled'}>+</button></div>${available?'':`<p class="stock-notice" role="status">${safe(stock)}</p>`}</div></article>`;}
const categoryList=['Todos','Pães','Doces','Salgados','Combos','Bolos'];
function home(){return `<main id="main" class="wrap page home-page"><section class="hero"><img src="./assets/bakery-hero.jpg" alt="Croissants artesanais dourados e uma xícara de café na Maison"><div class="hero-shade"></div><div class="hero-copy"><span class="eyebrow"><i></i> O MELHOR DO SEU DIA COMEÇA AQUI</span><h1>Um carinho<br>em cada <em>fornada.</em></h1><p>Pães artesanais, doces que abraçam e pequenos prazeres feitos para você.</p><a class="button button-primary" href="#vitrine">Explorar a vitrine <span>→</span></a><small class="hero-foot">✳ &nbsp; Ingredientes de verdade. Feito à mão.</small></div><span class="hero-number">01 <i>—</i> 04</span></section>
  <div class="promise-row"><div><span>♧</span><p><strong>Artesanal, de verdade</strong><small>Tempo, cuidado e bons ingredientes</small></p></div><div><span>❧</span><p><strong>Fresquinho todo dia</strong><small>Da nossa cozinha para sua mesa</small></p></div><div><span>↗</span><p><strong>Do seu jeito</strong><small>Retire na loja ou receba em casa</small></p></div></div>
  <section id="vitrine" class="catalog-section"><div class="section-head"><div><span class="eyebrow red">ESCOLHA SEU MOMENTO FAVORITO</span><h2 class="serif">Nossa vitrine<span class="red">.</span></h2></div><label class="search-box"><span aria-hidden="true">⌕</span><input id="product-search" type="search" placeholder="O que você procura?" aria-label="Buscar produtos"><button type="button" data-action="clear-search" aria-label="Limpar busca">×</button></label></div>
  <div class="category-bar"><div class="category-list" role="group" aria-label="Filtrar por categoria">${categoryList.map((name,index)=>`<button data-action="category" data-category="${name}" class="category-button ${index===0?'selected':''}" aria-pressed="${index===0}"><span>${['▦','♧','♡','✳','♢','◌'][index]}</span><small>${name}</small></button>`).join('')}</div><p>Sempre tem algo para adoçar seu dia.</p></div>
  <div class="catalog-tools"><span id="product-count">${PRODUCTS.length} delícias esperando por você</span><label>Ordenar por <select id="sort-products" aria-label="Ordenar produtos"><option value="favorites">Favoritos da casa</option><option value="lowest">Menor preço</option><option value="highest">Maior preço</option></select></label></div><div class="product-grid" id="product-grid">${PRODUCTS.map(p=>productCard(p)).join('')}</div><div class="no-results" id="no-results" hidden><span>⌕</span><h3>Nenhuma delícia encontrada.</h3><button class="text-button" data-action="reset-catalog">Limpar filtros</button></div></section>
  <section class="cake-callout"><div><span class="eyebrow">✳ &nbsp; PARA OS SEUS DIAS ESPECIAIS</span><h2 class="serif">Seu bolo.<br>Sua história.</h2><p>Escolha cada detalhe e deixe o resto com a gente.</p><a href="/montar-bolo" class="button button-primary">Monte seu bolo <span>→</span></a></div><img src="./assets/fatia-jardim-morango.jpg" alt="Bolo de morango com creme delicado" loading="lazy"></section></main>`;}
function promotions(){return `<main id="main" class="wrap page"><div class="page-intro"><span class="eyebrow red">SÓ POR TEMPO LIMITADO</span><h1 class="serif">Promoções<span class="red">.</span></h1><p>Descontos especiais em itens do nosso cardápio.</p></div><div class="product-grid promo-grid">${PROMOTIONS.map(p=>{const product=PRODUCTS.find(item=>item.id===p.productId);return product?`<article class="product-card"><div class="product-photo"><img src="${product.image}" alt="${safe(product.name)}" loading="lazy"><span class="discount">−${p.percent}%</span></div><div class="product-info"><p class="product-meta">${p.label}</p><h3>${safe(product.name)}</h3><p class="product-desc">${safe(product.description)}</p><div class="product-bottom"><span><s>${money(product.price)}</s> <strong>${money(priceWithPromo(product))}</strong></span><button class="add-button" data-action="add" data-id="${product.id}" aria-label="Adicionar ${safe(product.name)} ao carrinho">+</button></div></div></article>`:'';}).join('')}</div></main>`;}
function stars(amount){return `<span class="stars" aria-label="${amount} de 5 estrelas">${'★'.repeat(amount)}<span>${'★'.repeat(5-amount)}</span></span>`;}
function reviews(){const all=[...(state.orders||[]).filter(o=>o.review).map(o=>({name:'Cliente Maison',...o.review,date:o.date})),...REVIEWS];const average=(all.reduce((sum,item)=>sum+item.rating,0)/all.length).toFixed(1).replace('.',',');return `<main id="main" class="wrap page"><div class="page-intro"><span class="eyebrow red">QUEM PROVA, CONTA</span><h1 class="serif">Avaliações<span class="red">.</span></h1></div><div class="rating-summary"><strong>${average}</strong><div>${stars(Math.round(Number(average)))}<small>${all.length} avaliações de compras</small></div><a class="button button-outline" href="/pedidos">Avaliar meu pedido</a></div><div class="review-grid">${all.map(item=>`<article class="review-card"><div class="review-top"><h2>${safe(item.name)}</h2>${stars(item.rating)}</div>${item.text?`<p>“${safe(item.text)}”</p>`:''}<small>${safe((item.date||'').split('-').reverse().join('/'))} · Compra verificada</small></article>`).join('')}</div><p class="note">Somente clientes logados podem avaliar, a partir dos próprios pedidos.</p></main>`;}
function cakeBuilder(){const c=state.cakeConfig||{tiers:2,dough:'Red Velvet',fillings:['Doce de Leite','Morango'],shape:'Coração',frosting:'Branca',size:20,berries:true,flowers:true,note:''};const base={15:120,20:180,25:240}[c.size]||120;const price=base+(c.shape==='Coração'?20:0)+(c.dough==='Red Velvet'?15:0)+(c.fillings.length*10);const descriptions=`${c.tiers} ${c.tiers===2?'andares':'andar'} · ${c.shape} · ${c.size} cm · ${c.dough} · ${c.fillings.join(' + ')} · Cobertura ${c.frosting}${c.berries?' · Frutas vermelhas':''}${c.flowers?' · Flores':''}`;return `<main id="main" class="cake-page"><div class="wrap builder-heading"><a class="back-link" href="/">← Nossa vitrine</a><div><span class="eyebrow red">SEU MOMENTO. SEU BOLO.</span><h1 class="serif">Monte seu bolo<span class="red">.</span></h1><p>Camadas de carinho, do seu jeito.</p></div></div><div class="wrap builder-layout"><section class="builder-controls"><div class="builder-title"><h2>Os detalhes fazem a diferença</h2><button class="icon-button" data-action="cake-reset" aria-label="Restaurar escolhas">↺</button></div>
  ${cakeChoice('Andares','tiers',['1','2'],c.tiers===1?'1':'2')}${cakeChoice('Massa','dough',['Baunilha','Chocolate','Red Velvet'],c.dough,'Red Velvet + R$ 15')}${cakeChoice('Recheio','fillings',['Brigadeiro','Doce de Leite','Creme de Baunilha','Morango'],c.fillings,'Até 2 sabores · + R$ 10 por sabor')}${cakeChoice('Formato','shape',['Redondo','Quadrado','Coração'],c.shape,'Coração + R$ 20')}${cakeChoice('Cobertura','frosting',['Branca','Chocolate','Naked','Rosa delicado'],c.frosting)}${cakeChoice('Tamanho','size',['15','20','25'],String(c.size),'10 · 20 · 30 fatias')}
  <div class="builder-choice"><h3>Decoração</h3><div class="pill-row"><button class="pill ${c.berries?'is-on':''}" data-action="cake-toggle" data-key="berries" aria-pressed="${c.berries}">Frutas Vermelhas</button><button class="pill ${c.flowers?'is-on':''}" data-action="cake-toggle" data-key="flowers" aria-pressed="${c.flowers}">Flores</button></div></div><details class="builder-note"><summary>Uma mensagem especial <span>⌄</span></summary><label for="cake-note">Mensagem ou observação</label><textarea id="cake-note" maxlength="300" placeholder="Uma mensagem para um dia especial…">${safe(c.note)}</textarea></details><div class="builder-total"><span>Seu bolo personalizado<small>Feito sob encomenda</small></span><strong>${money(price)}</strong></div><button class="button button-primary button-wide" data-action="add-cake" ${c.fillings.length?'':'disabled'}>♧ &nbsp; Adicionar ao carrinho <span>→</span></button>${!c.fillings.length?'<p class="tiny center muted">Escolha pelo menos um recheio para continuar.</p>':''}</section><aside class="cake-preview"><span class="preview-overline">ATELIÊ MAISON &nbsp; · &nbsp; PRÉVIA ILUSTRATIVA</span><img src="./assets/cake-builder.webp" alt="Bolo decorado em formato de coração, prévia ilustrativa"><div><span class="eyebrow red">FEITO PARA VOCÊ</span><h2 class="serif">Um doce que é só seu.</h2><p>${safe(descriptions)}</p><small>Prévia ilustrativa. A decoração pode variar.</small></div></aside></div><section class="wrap cake-catalog"><span class="eyebrow red">INSPIRE-SE</span><h2 class="serif">Nosso catálogo de bolos</h2><p>Toque em uma combinação para começar por ela.</p><div class="cake-inspiration">${[['Baunilha','Creme de Baunilha','bolo-1-andar-redondo-baunilha-creme-de-baunilha-branca.webp'],['Chocolate','Brigadeiro','bolo-1-andar-redondo-chocolate-brigadeiro-chocolate.webp'],['Red Velvet','Doce de Leite','bolo-2-andares-quadrado-red-velvet-brigadeiro-doce-de-leite-branca.webp']].map(([dough,filling,image])=>`<button class="inspiration-card" data-action="cake-inspiration" data-dough="${dough}" data-filling="${filling}"><img src="./assets/${image}" alt="Bolo ${dough} e ${filling}" loading="lazy"><span>2 andares · Redondo</span><small>${dough} · ${filling}</small></button>`).join('')}</div></section></main>`;}
function cakeChoice(title,key,options,value,help=''){return `<fieldset class="builder-choice"><legend>${title}${help?` <small>${help}</small>`:''}</legend><div class="pill-row">${options.map(option=>{const chosen=key==='fillings'?value.includes(option):String(value)===String(option);const disabled=key==='frosting'&&option==='Rosa delicado'&&!(currentCake().tiers===2&&currentCake().fillings.includes('Doce de Leite')&&currentCake().fillings.includes('Morango')&&currentCake().berries&&currentCake().flowers);return `<button type="button" class="pill ${chosen?'is-on':''}" data-action="cake-option" data-key="${key}" data-value="${option}" aria-pressed="${chosen}" ${disabled?'disabled title="Ainda não fotografada para esta combinação."':''}>${key==='tiers'?`${option} ${option==='1'?'andar':'andares'}`:key==='size'?`${option} cm`:option}</button>`;}).join('')}</div>${key==='fillings'?`<small class="field-hint">${value.length}/2 · + R$ 10 por sabor</small>`:''}</fieldset>`;}
function auth(){return `<main id="main" class="wrap auth-page"><a class="back-link" href="/">← Nossa vitrine</a><div class="auth-card"><span class="eyebrow red">BEM-VINDO À MAISON</span><h1 class="serif" id="auth-title">É bom ter você aqui.</h1><p class="auth-subtitle">Entre para acompanhar seus pedidos e falar com a nossa equipe.</p><div class="auth-tabs"><button data-action="auth-mode" data-mode="login" class="selected">Entrar</button><button data-action="auth-mode" data-mode="signup">Criar conta</button></div><form id="auth-form" class="form-stack"><label class="field-label signup-field" hidden>Nome completo<input name="name" autocomplete="name" minlength="2" maxlength="120"></label><label class="field-label">E-mail<input name="email" type="email" autocomplete="email" required maxlength="254"></label><label class="field-label password-field">Senha<input name="password" type="password" autocomplete="current-password" required minlength="8" maxlength="128"></label><button type="submit" class="button button-primary button-wide">Entrar na conta <span>→</span></button><p class="form-message" id="auth-message" role="status"></p></form><button class="text-button reset-link" data-action="auth-reset">Esqueci minha senha</button><section class="demo-login"><h2>Perfis de demonstração</h2><p>Use uma destas contas fictícias para explorar pedidos e gestão.</p>${DEMOS.map(account=>`<button class="demo-profile" data-action="demo-login" data-id="${account.id}"><span>${account.role==='admin'?'♙':account.role==='employee'?'♧':'♡'}</span><span><strong>${safe(account.name)}</strong><small>${account.email}</small></span><span>→</span></button>`).join('')}</section><p class="demo-disclaimer">Acesso demonstrativo somente no navegador. Cadastro, recuperação de senha e login social exigem integração com um serviço de conta.</p></div></main>`;}
function gated(title,description,icon='♙'){if(!demosigned())return `<main id="main" class="wrap empty-page"><span class="empty-icon">${icon}</span><h1 class="serif">${title}</h1><p>${description}</p><a class="button button-primary" href="/auth">Entrar na conta <span>→</span></a></main>`;return null;}
function cart(){const gate=gated('Entre para fazer seu pedido.','Os pedidos ficam disponíveis apenas para quem está logado.','♧');if(gate)return gate;if(!state.cart.length)return `<main id="main" class="wrap empty-page"><span class="empty-icon">♧</span><h1 class="serif">Seu carrinho espera por um carinho.</h1><p>Escolha algo fresquinho para começar.</p><a class="button button-primary" href="/">Explorar a vitrine <span>→</span></a><a class="text-button" href="/pedidos">Ver meus pedidos</a></main>`;return `<main id="main" class="wrap page"><div class="page-intro cart-heading"><div><span class="eyebrow red">QUASE NA SUA MESA</span><h1 class="serif">Seu carrinho<span class="red">.</span></h1></div><a href="/pedidos" class="button button-outline">Meus pedidos</a></div><form class="checkout-grid" id="checkout-form"><section class="cart-lines">${state.cart.map(item=>`<article class="cart-item"><img src="${item.image}" alt="${safe(item.name)}"><div class="cart-product"><h2>${safe(item.name)}</h2><p>${safe(item.description)}</p>${item.cake?.note?`<small>Observação: ${safe(item.cake.note)}</small>`:''}${item.requiresPreparation?`<fieldset class="prep-choice"><legend>Preparo do combo · obrigatório</legend><label><input type="radio" name="prep-${item.id}" data-prep="fried" ${item.preparation==='fried'?'checked':''}> Frito pela loja</label><label><input type="radio" name="prep-${item.id}" data-prep="frozen" ${item.preparation==='frozen'?'checked':''}> Congelado para fritar em casa</label></fieldset>`:''}<div class="quantity-controls"><button type="button" data-action="quantity" data-id="${item.id}" data-delta="-1" aria-label="Diminuir ${safe(item.name)}">−</button><span>${item.quantity}</span><button type="button" data-action="quantity" data-id="${item.id}" data-delta="1" aria-label="Aumentar ${safe(item.name)}">+</button><button type="button" class="remove-button" data-action="remove" data-id="${item.id}">Remover</button></div></div><strong class="line-price">${money(item.price*item.quantity)}</strong></article>`).join('')}
  <div class="checkout-fields"><h2>Como deseja receber?</h2><div class="delivery-options"><label class="delivery-card"><input type="radio" name="method" value="pickup" checked><span>⌂</span><b>Retirar na loja</b><small>Sem taxa de entrega</small></label><label class="delivery-card"><input type="radio" name="method" value="delivery"><span>↗</span><b>Receber em casa</b><small>Taxa de R$ 12,00</small></label></div><div class="form-grid"><label class="field-label">Data desejada<input type="date" name="date" min="${new Date().toISOString().slice(0,10)}" required></label><label class="field-label">Horário<select name="time" required><option value="">Escolha um horário</option>${['09:00','10:00','11:00','12:00','13:00','14:00','15:00','16:00','17:00','18:00'].map(t=>`<option>${t}</option>`).join('')}</select></label><label class="field-label address-field" hidden>Endereço de entrega<input name="address" autocomplete="street-address"></label><label class="field-label">Forma de pagamento<select name="payment" required><option value="">Escolha uma forma</option><option>Pix</option><option>Cartão de crédito</option><option>Cartão de débito</option><option class="pickup-only">Pagar na retirada</option></select></label></div></div></section><aside class="order-summary"><span class="eyebrow red">RESUMO DO PEDIDO</span><h2 class="serif">Um bom momento.</h2><p class="branch-address">⌖ &nbsp; Maison ${safe(branch().name)} · ${safe(branch().address)}</p><label class="field-label coupon-label">Cupom de desconto<div class="coupon-row"><input name="coupon" placeholder="Código do cupom"><button type="button" class="button button-outline" data-action="apply-coupon">Aplicar</button></div><small id="coupon-message"></small></label><div class="summary-lines"><p><span>Subtotal</span><strong>${money(subtotal())}</strong></p><p><span>Entrega</span><strong id="delivery-fee">Grátis</strong></p><p class="summary-total"><span>Total</span><strong id="order-total">${money(subtotal())}</strong></p></div><p class="demo-disclaimer">Compra demonstrativa. Nenhum pagamento será processado.</p><button class="button button-primary button-wide" type="submit">Confirmar pedido <span>→</span></button><p id="checkout-message" role="status" class="form-message"></p></aside></form></main>`;}
function orderStatus(status){return ({scheduled:'Vai ser feito',preparing:'Sendo feito',delivering:'Sendo entregue',cancelled:'Cancelado'})[status]||'Vai ser feito';}
function orders(){const gate=gated('Entre para ver seus pedidos.','Pedidos e avaliações ficam disponíveis apenas para quem está logado.','□');if(gate)return gate;const list=(state.orders||[]).filter(order=>!order.demoOwner||order.demoOwner===state.demoAccountId);if(!list.length)return `<main id="main" class="wrap empty-page"><span class="empty-icon">□</span><h1 class="serif">Seus bons momentos ficam aqui.</h1><p>Você ainda não tem pedidos. Que tal escolher uma delícia?</p><a class="button button-primary" href="/">Ver nossa vitrine <span>→</span></a></main>`;const selected=list.find(o=>o.id===state.selectedOrder)||list[0];return `<main id="main" class="wrap page"><div class="page-intro"><span class="eyebrow red">DO NOSSO FORNO ATÉ VOCÊ</span><h1 class="serif">Meus pedidos<span class="red">.</span></h1><p>Sua encomenda está registrada nesta demonstração.</p></div><div class="orders-layout"><section><div class="order-tabs">${list.map(order=>`<button class="button ${selected.id===order.id?'button-primary':'button-outline'}" data-action="select-order" data-id="${order.id}">#${order.id}</button>`).join('')}</div><div class="order-detail"><div class="order-top"><div><h2 class="serif">Pedido #${selected.id}</h2><p>Maison ${safe(BRANCHES.find(b=>b.id===selected.branchId)?.name||'Jardins')} · ${safe(selected.date)} às ${safe(selected.time)}</p></div><span class="status-pill">◷ &nbsp; ${orderStatus(selected.status)}</span></div><div class="order-progress"><div class="current"><b>✓</b><span>Aguardando confirmação</span></div><div><b>2</b><span>Em preparo</span></div><div><b>3</b><span>${selected.method==='pickup'?'Disponível para retirada':'Saiu para entrega'}</span></div></div>${selected.items.map(item=>`<div class="order-line"><img src="${item.image}" alt=""><span><strong>${item.quantity}× ${safe(item.name)}</strong><small>${safe(item.description)}</small></span><b>${money(item.quantity*item.price)}</b></div>`).join('')}<div class="summary-total"><span>Total</span><strong>${money(selected.total)}</strong></div></div><section class="review-form"><h2>Avalie seu pedido</h2><div class="rating-input" role="group" aria-label="Sua nota">${[1,2,3,4,5].map(i=>`<button type="button" data-action="rating" data-rating="${i}" aria-label="${i} estrelas" aria-pressed="${(state.reviewDraft?.rating||0)>=i}">★</button>`).join('')}</div><label class="field-label">Conte como foi sua experiência<textarea id="review-text" maxlength="500" placeholder="O que você achou do seu pedido?">${safe(state.reviewDraft?.text||'')}</textarea></label><button class="button button-outline" data-action="save-review">Enviar avaliação</button></section></section><aside class="order-aside"><h2 class="serif">Fale com a Maison.</h2><p>Deixe uma mensagem sobre este pedido nesta demonstração.</p><div class="chat-demo">${(selected.messages||[]).map(m=>`<p class="${m.customer?'own':''}">${safe(m.text)}</p>`).join('')}</div><form id="order-message-form"><label class="field-label">Sua mensagem<textarea name="message" maxlength="500" required placeholder="Escreva uma mensagem…"></textarea></label><button class="button button-primary button-wide">Enviar mensagem →</button></form></aside></div></main>`;}

function accountView(){const gate=gated('Entre para ver seus dados.','Acesse sua conta para consultar seus dados pessoais.');if(gate)return gate;const account=demosigned();return `<main id="main" class="wrap page"><div class="platform-heading"><div><span class="eyebrow red">SUA CONTA MAISON</span><h1 class="serif">Meu cadastro<span class="red">.</span></h1></div><a href="/testes" class="button button-outline">Painel de testes</a></div><div class="platform-tabs">${link('/conta','Meu cadastro')}${link('/pedidos','Meus pedidos')}${link('/atendimento','Atendimento')}${account.role==='admin'||account.role==='employee'?link('/loja','Gestão da loja'):''}${account.role==='admin'?link('/gestao','Gerenciamento'):''}</div><section class="platform-panel"><h2>Seus dados</h2><p class="muted">Esta área está em modo demonstrativo. Dados pessoais e alterações não são enviados a um serviço de conta.</p><form id="profile-form" class="form-grid"><label class="field-label">Nome completo<input name="name" autocomplete="name" value="${safe(account.name.split('·').pop().trim())}" required></label><label class="field-label">E-mail<input type="email" value="${safe(account.email)}" disabled></label><label class="field-label">Filial preferida<select name="branch">${BRANCHES.map(b=>`<option value="${b.id}" ${b.id===state.branchId?'selected':''}>${b.name}</option>`).join('')}</select></label><button class="button button-primary">Salvar neste navegador</button></form><p id="profile-message" class="form-message" role="status"></p></section></main>`;}
function support(){const gate=gated('Entre para falar com a Maison.','Entre na sua conta para consultar seu histórico privado de atendimento.','☏');if(gate)return gate;const conversations=state.conversations||[];const selected=conversations.find(c=>c.id===state.selectedConversation)||null;return `<main id="main" class="wrap page"><div class="platform-heading"><div><span class="eyebrow red">ESTAMOS AQUI PARA AJUDAR</span><h1 class="serif">${demosigned()?.role==='admin'||demosigned()?.role==='employee'?'Central de atendimento':'Fale com a Maison'}<span class="red">.</span></h1></div><button class="button button-primary" data-action="new-conversation">+ Nova conversa</button></div><p class="demo-disclaimer">As conversas desta tela são salvas apenas no navegador e não chegam à equipe Maison.</p><div class="support-layout"><aside class="conversation-list"><label class="field-label">Pesquisar assunto<input id="conversation-search" placeholder="Buscar conversa"></label>${conversations.map(c=>`<button class="conversation-button ${selected?.id===c.id?'active':''}" data-action="select-conversation" data-id="${c.id}"><span class="avatar">M</span><span><strong>${safe(c.subject)}</strong><small>${safe(c.messages.at(-1)?.text||'Nova conversa')}</small></span></button>`).join('')||'<p class="muted empty-conversations">Ainda não há conversas.</p>'}</aside><section class="conversation-chat">${selected?`<div class="chat-heading"><button data-action="back-conversations" class="mobile-back">← Conversas</button><h2>${safe(selected.subject)}</h2><small>Conversa demonstrativa</small></div><div class="chat-messages">${selected.messages.map(m=>`<p class="chat-message ${m.own?'own':''}">${safe(m.text)}<small>${m.own?'Você':'Maison'}</small></p>`).join('')}</div><form id="support-message-form"><label class="field-label">Sua mensagem<textarea name="message" required maxlength="500" placeholder="Escreva sua mensagem…"></textarea></label><button class="button button-primary">Enviar →</button></form>`:'<div class="empty-chat"><span>☏</span><h2>Converse com a gente.</h2><p>Abra uma conversa para falar com a Maison.</p><button class="button button-outline" data-action="new-conversation">Nova conversa</button></div>'}</section></div></main>`;}
function tests(){const account=demosigned();if(!account)return `<main id="main" class="wrap page"><span class="eyebrow red">DADOS FICTÍCIOS · AMBIENTE SEPARADO</span><h1 class="serif">Área de testes<span class="red">.</span></h1><p class="muted">Entre com um perfil de demonstração para explorar a loja, os pedidos e as ferramentas de gestão. Esses perfis não são contas reais.</p><a class="button button-primary" href="/auth">Escolher perfil de teste →</a></main>`;const owned=(state.orders||[]).filter(o=>account.role==='admin'||(account.role==='employee'?o.branchId===account.branchId:o.demoOwner===account.id));const itemCount=owned.reduce((sum,o)=>sum+o.items.reduce((n,i)=>n+i.quantity,0),0);return `<main id="main" class="wrap page"><div class="platform-heading"><div><span class="eyebrow red">DEMONSTRAÇÃO ISOLADA · DADOS FICTÍCIOS</span><h1 class="serif">${safe(account.name)}<span class="red">.</span></h1><p>${account.role==='admin'?'Todas as filiais':account.role==='employee'?`Equipe da filial ${BRANCHES.find(b=>b.id===account.branchId)?.name}`:'Seus pedidos de teste'}</p></div><button class="button button-outline" data-action="logout">Sair dos testes</button></div><div class="test-actions"><a class="button button-primary" href="/">Fazer novo pedido</a><a class="button button-outline" href="/carrinho">Ver carrinho</a></div><div class="stats-grid"><article><small>Pedidos visíveis</small><strong>${owned.length}</strong></article><article><small>Itens encomendados</small><strong>${itemCount}</strong></article><article><small>Total demonstrativo</small><strong>${money(owned.reduce((sum,o)=>sum+o.total,0))}</strong></article></div><h2 class="serif subsection">Pedidos de teste</h2>${owned.length?`<div class="demo-orders">${owned.map(order=>`<article class="demo-order"><div><h3>Pedido #${order.id}</h3><p>Maison ${BRANCHES.find(b=>b.id===order.branchId)?.name} · ${safe(order.date)}</p><span class="status-pill">${orderStatus(order.status)}</span></div><strong>${money(order.total)}</strong>${account.role==='admin'||account.role==='employee'?`<label class="field-label">Alterar situação<select data-action="demo-status" data-id="${order.id}">${[['scheduled','Vai ser feito'],['preparing','Sendo feito'],['delivering','Sendo entregue'],['cancelled','Cancelado']].map(([v,l])=>`<option value="${v}" ${order.status===v?'selected':''}>${l}</option>`).join('')}</select></label>`:''}</article>`).join('')}</div>`:'<p class="muted">Ainda não há pedidos neste perfil. Faça um pedido de demonstração para começar.</p>'}${account.role==='admin'||account.role==='employee'?`<section class="platform-panel demo-management"><h2>${account.role==='admin'?'Ferramentas de demonstração':'Estoque da loja'}</h2><p class="muted">Os ajustes abaixo ficam somente neste navegador e não alteram o catálogo real.</p><label class="field-label">Produto<select id="demo-product">${PRODUCTS.map(p=>`<option value="${p.id}">${safe(p.name)}</option>`).join('')}</select></label><label class="field-label">Disponibilidade<select id="demo-stock"><option>Disponível</option><option>Esgotado</option><option>Em produção</option></select></label><button class="button button-outline" data-action="save-demo-stock">Salvar disponibilidade local</button><p id="demo-stock-message" class="form-message" role="status"></p></section>`:''}<section class="platform-panel"><h2>Cupons demonstrativos</h2><p class="muted">Use o cupom <strong>MAISON10</strong> para um desconto de teste no carrinho. Não há cobranças reais.</p></section></main>`;}
function storeManagement(){const account=demosigned();if(!account)return gated('Entre para acessar a gestão.','Área de gestão disponível aos perfis autorizados.');if(account.role !== 'admin')return `<main id="main" class="wrap page"><h1 class="serif">Gestão da loja</h1><p>Seu perfil não possui acesso a este painel.</p></main>`;const branchId = state.stockBranch || 'jardins'; const available = state.branchStock?.[branchId] || {};return `<main id="main" class="wrap page"><div class="platform-heading"><div><span class="eyebrow red">OPERAÇÃO MAISON</span><h1 class="serif">Gestão da loja<span class="red">.</span></h1></div><span class="demo-disclaimer">Modo local de demonstração</span></div><div class="platform-tabs"><button data-action="store-tab" data-tab="stock" class="selected">Estoque</button><button data-action="store-tab" data-tab="campaigns">Cardápios sazonais</button></div><section id="stock-panel" class="platform-panel"><label class="field-label">Filial<select id="stock-branch">${BRANCHES.map(b=>`<option value="${b.id}">${b.name}</option>`).join('')}</select></label><label class="field-label">Buscar produto<input id="stock-search" placeholder="Nome do produto"></label><div class="stock-list">${PRODUCTS.map(p=>`<article data-product-row="${safe(p.name.toLocaleLowerCase('pt-BR'))}"><img src="${p.image}" alt=""><span><strong>${safe(p.name)}</strong><small>${p.category}</small></span><label class="field-label">Status<select data-stock-id="${p.id}"><option>Disponível</option><option ${available[p.id]==='Esgotado'?'selected':''}>Esgotado</option><option ${available[p.id]==='Em produção'?'selected':''}>Em produção</option></select></label></article>`).join('')}</div></section><section id="campaigns-panel" class="platform-panel" hidden><h2>Campanhas</h2><p>Não há campanhas cadastradas nesta demonstração estática.</p><button class="button button-outline" data-action="campaign-info">Nova campanha</button></section><p class="demo-disclaimer">O serviço de gestão conectado não foi migrado. Estes ajustes ficam no navegador e não atualizam o estoque real.</p></main>`;}
function management(){const account=demosigned();if(!account)return gated('Entre para acessar o gerenciamento.','Esta área requer um perfil autorizado.');if(account.role !== 'admin')return `<main id="main" class="wrap page"><h1 class="serif">Gerenciamento</h1><p>Seu perfil não possui acesso a este painel.</p></main>`;return `<main id="main" class="wrap page"><div class="platform-heading"><div><span class="eyebrow red">PAINEL MAISON</span><h1 class="serif">Gerenciamento<span class="red">.</span></h1></div></div><div class="stats-grid">${[['Filiais','3'],['Pessoas','0'],['Empresas','0'],['Proprietários','0']].map(([label,n])=>`<article><small>${label}</small><strong>${n}</strong></article>`).join('')}</div><div class="platform-panel"><h2>Cadastros e permissões</h2><p>O gerenciamento de cadastros, permissões e dados privados depende do serviço de conta e não foi migrado para esta interface estática.</p><div class="management-tabs">${['Filiais','Pessoas','Empresas','Proprietários'].map((label,i)=>`<button class="button ${i===0?'button-primary':'button-outline'}" data-action="registry-tab">${label}</button>`).join('')}</div><div class="empty-registry"><span>⌕</span><h3>Nenhum cadastro disponível</h3><p>Cadastros reais não são carregados nesta demonstração.</p></div></div><p class="demo-disclaimer">A interface está pronta para um adaptador opcional, mas alterações e leituras privadas não são simuladas como operações reais.</p></main>`;}
function resetPassword(){return `<main id="main" class="wrap auth-page"><div class="auth-card"><span class="eyebrow red">ACESSO À SUA CONTA</span><h1 class="serif">Sua nova senha</h1><p>Abra o link de recuperação enviado por e-mail para continuar.</p><p class="demo-disclaimer">A recuperação de senha precisa de um serviço de conta conectado e ainda não está disponível nesta demonstração.</p><a href="/auth" class="button button-primary">Voltar para entrar</a></div></main>`;}
const ROUTES={'/':home,'/avaliacoes':reviews,'/auth':auth,'/carrinho':cart,'/montar-bolo':cakeBuilder,'/pedidos':orders,'/promocoes':promotions,'/reset-password':resetPassword,'/testes':tests,'/conta':accountView,'/atendimento':support,'/gestao':management,'/loja':storeManagement};
function render(){const path=currentPath();const view=ROUTES[path]||home;document.querySelector('#app').innerHTML=shell(view()).replaceAll('href="/','href="#/');document.title=`${({'/':'Nossa vitrine','/avaliacoes':'Avaliações','/auth':'Sua conta','/carrinho':'Seu carrinho','/montar-bolo':'Monte seu bolo','/pedidos':'Meus pedidos','/promocoes':'Promoções','/reset-password':'Nova senha','/testes':'Área de testes','/conta':'Meu cadastro','/atendimento':'Atendimento','/gestao':'Gerenciamento','/loja':'Gestão da loja'})[path]||'Maison'} | Maison — Padaria & Doceria`;if(path==='/')filterProducts();syncCheckout();}
function navigate(path){const route=path.replace(/\/$/,'')||'/';if(currentPath()===route){render();window.scrollTo({top:0,behavior:'instant'});return;}window.location.hash=route;window.scrollTo({top:0,behavior:'instant'});}
document.addEventListener('click',event=>{const anchor=event.target.closest('a[href]');if(anchor&&!event.metaKey&&!event.ctrlKey&&!event.shiftKey&&anchor.origin===location.origin&&!anchor.hash){event.preventDefault();navigate(anchor.pathname);return;}const button=event.target.closest('[data-action]');if(!button)return;const action=button.dataset.action;switch(action){case'branch':document.querySelector('#branch-dialog')?.showModal();break;case'choose-branch':state.branchId=button.dataset.id;persist();render();toast(`Loja ${branch().name} selecionada.`);break;case'menu':{const nav=document.querySelector('.mobile-nav');nav.classList.toggle('open');button.setAttribute('aria-expanded',nav.classList.contains('open'));break;}case'add':addProduct(button.dataset.id);break;case'category':document.querySelectorAll('.category-button').forEach(b=>{const on=b===button;b.classList.toggle('selected',on);b.setAttribute('aria-pressed',String(on));});filterProducts();break;case'clear-search':{const input=document.querySelector('#product-search');if(input){input.value='';filterProducts();input.focus();}break;}case'reset-catalog':document.querySelector('#product-search').value='';document.querySelector('[data-category="Todos"]').click();break;case'quantity':changeQuantity(button.dataset.id,Number(button.dataset.delta));break;case'remove':changeQuantity(button.dataset.id,0);break;case'cake-option':cakeOption(button.dataset.key,button.dataset.value);break;case'cake-toggle':{const c=currentCake();c[button.dataset.key]=!c[button.dataset.key];saveCake(c);render();break;}case'cake-reset':state.cakeConfig={tiers:2,dough:'Red Velvet',fillings:['Doce de Leite','Morango'],shape:'Coração',frosting:'Branca',size:20,berries:true,flowers:true,note:''};persist();render();break;case'add-cake':addCake();break;case'cake-inspiration':{const c=currentCake();c.dough=button.dataset.dough;c.fillings=[button.dataset.filling];saveCake(c);render();window.scrollTo({top:0,behavior:'smooth'});break;}case'auth-mode':setAuthMode(button.dataset.mode);break;case'auth-reset':navigate('/reset-password');break;case'demo-login':loginDemo(button.dataset.id);break;case'logout':state.demoAccountId=null;persist();navigate('/auth');toast('Você saiu da demonstração.');break;case'select-order':state.selectedOrder=button.dataset.id;state.reviewDraft=null;persist();render();break;case'rating':state.reviewDraft={...(state.reviewDraft||{}),rating:Number(button.dataset.rating)};persist();render();break;case'save-review':saveReview();break;case'new-conversation':newConversation();break;case'select-conversation':state.selectedConversation=button.dataset.id;persist();render();break;case'back-conversations':state.selectedConversation=null;persist();render();break;case'apply-coupon':applyCoupon();break;case'save-demo-stock':saveDemoStock();break;case'store-tab':storeTab(button.dataset.tab);break;case'campaign-info':toast('Campanhas reais exigem o serviço de gestão conectado.');break;case'registry-tab':document.querySelectorAll('.management-tabs .button').forEach(b=>b.classList.remove('button-primary'));button.classList.add('button-primary');break;}}
);
window.addEventListener('hashchange',()=>{if(window.location.hash.startsWith('#/'))render();});
document.addEventListener('input',event=>{if(event.target.id==='product-search')filterProducts();if(event.target.id==='sort-products')filterProducts();if(event.target.id==='stock-search')filterStock();if(event.target.id==='conversation-search')filterConversations();if(event.target.id==='cake-note'){const c=currentCake();c.note=event.target.value;saveCake(c);}if(event.target.name==='method')syncCheckout();});
document.addEventListener('change',event=>{if(event.target.name==='method')syncCheckout();if(event.target.dataset.prep){const item=state.cart.find(i=>i.id===event.target.name.replace('prep-',''));if(item)item.preparation=event.target.dataset.prep;persist();}if(event.target.matches('[data-stock-id]')){state.stock={...(state.stock||{}),[event.target.dataset.stockId]:event.target.value};persist();toast('Disponibilidade atualizada somente neste navegador.');}if(event.target.dataset.action==='demo-status'){const order=state.orders.find(o=>o.id===event.target.dataset.id);if(order){order.status=event.target.value;persist();toast('Situação atualizada nesta demonstração.');}}});
document.addEventListener('submit',event=>{if(event.target.id==='auth-form'){event.preventDefault();authSubmit(event.target);}if(event.target.id==='checkout-form'){event.preventDefault();checkout(event.target);}if(event.target.id==='order-message-form'){event.preventDefault();sendOrderMessage(event.target);}if(event.target.id==='support-message-form'){event.preventDefault();sendSupportMessage(event.target);}if(event.target.id==='profile-form'){event.preventDefault();const values=new FormData(event.target);state.profileName=values.get('name');state.branchId=values.get('branch');persist();document.querySelector('#profile-message').textContent='Alterações salvas somente neste navegador.';toast('Cadastro atualizado localmente.');}});
document.addEventListener('submit',event=>{if(event.target.id!=='checkout-form')return;const unavailable=state.cart.find(item=>!item.cake&&stockStatus(item.productId||item.id)!=='Disponível');if(!unavailable)return;event.preventDefault();event.stopImmediatePropagation();const message=document.querySelector('#checkout-message');message.textContent=`${unavailable.name} está ${stockStatus(unavailable.productId||unavailable.id).toLocaleLowerCase('pt-BR')} na loja selecionada. Remova o item para continuar.`;message.className='form-message error-text';},true);
function filterProducts(){const grid=document.querySelector('#product-grid');if(!grid)return;const category=document.querySelector('.category-button.selected')?.dataset.category||'Todos';const query=(document.querySelector('#product-search')?.value||'').trim().toLocaleLowerCase('pt-BR');const sort=document.querySelector('#sort-products')?.value||'favorites';let list=PRODUCTS.filter(p=>(category==='Todos'||p.category===category)&&`${p.name} ${p.description}`.toLocaleLowerCase('pt-BR').includes(query));if(sort==='lowest')list.sort((a,b)=>priceWithPromo(a)-priceWithPromo(b));if(sort==='highest')list.sort((a,b)=>priceWithPromo(b)-priceWithPromo(a));grid.innerHTML=list.map(p=>productCard(p)).join('');document.querySelector('#product-count').textContent=`${list.length} delícias esperando por você`;document.querySelector('#no-results').hidden=list.length>0;}
function addProduct(id){const p=PRODUCTS.find(item=>item.id===id);if(!p)return;if(stockStatus(id)!=='Disponível'){toast(`${p.name}: ${stockStatus(id).toLocaleLowerCase('pt-BR')}.`);return;}if(!demosigned()){toast('Entre com um perfil de demonstração para fazer seu pedido.');navigate('/auth');return;}const existing=state.cart.find(i=>i.id===id);if(existing)existing.quantity++;else state.cart.push({...p,price:priceWithPromo(p),quantity:1,productId:id,requiresPreparation:p.category==='Combos'});persist();render();toast(`${p.name} adicionado ao carrinho.`);}
function changeQuantity(id,delta){const item=state.cart.find(i=>i.id===id);if(!item)return;item.quantity=delta===0?0:item.quantity+delta;state.cart=state.cart.filter(i=>i.quantity>0);persist();render();}
function currentCake(){return {...(state.cakeConfig||{tiers:2,dough:'Red Velvet',fillings:['Doce de Leite','Morango'],shape:'Coração',frosting:'Branca',size:20,berries:true,flowers:true,note:''}),fillings:[...((state.cakeConfig||{fillings:['Doce de Leite','Morango']}).fillings||[])]};}
function saveCake(config){state.cakeConfig=config;persist();}
function cakeOption(key,value){const c=currentCake();if(key==='fillings'){if(c.fillings.includes(value))c.fillings=c.fillings.filter(i=>i!==value);else if(c.fillings.length<2)c.fillings.push(value);else{toast('Escolha até 2 recheios. Remova um para trocar.');return;}}else if(key==='tiers')c.tiers=Number(value);else if(key==='size')c.size=Number(value);else c[key]=value;if(c.frosting==='Rosa delicado'&&!(c.tiers===2&&c.fillings.includes('Doce de Leite')&&c.fillings.includes('Morango')&&c.berries&&c.flowers))c.frosting='Branca';saveCake(c);render();}
function addCake(){const c=currentCake();if(!c.fillings.length)return;if(!demosigned()){toast('Entre com um perfil de demonstração para pedir seu bolo.');navigate('/auth');return;}const price=({15:120,20:180,25:240}[c.size]||120)+(c.shape==='Coração'?20:0)+(c.dough==='Red Velvet'?15:0)+c.fillings.length*10;const id=`cake-${Date.now()}`;const item={id,productId:id,name:'Bolo personalizado',description:`${c.tiers} ${c.tiers===2?'andares':'andar'} · ${c.shape} · ${c.size} cm · ${c.dough} · ${c.fillings.join(' + ')} · Cobertura ${c.frosting}${c.flowers?' · Flores':''}${c.berries?' · Frutas vermelhas':''}`,price,image:'./assets/cake-builder.webp',quantity:1,cake:c};state.cart.push(item);persist();navigate('/carrinho');toast('Seu bolo foi adicionado ao carrinho!');}
function setAuthMode(mode){document.querySelectorAll('.auth-tabs button').forEach(b=>b.classList.toggle('selected',b.dataset.mode===mode));document.querySelector('.signup-field').hidden=mode!=='signup';document.querySelector('.password-field').hidden=false;document.querySelector('.password-field input').required=true;document.querySelector('.password-field input').autocomplete=mode==='signup'?'new-password':'current-password';document.querySelector('#auth-title').textContent=mode==='signup'?'Crie sua conta':'É bom ter você aqui.';const submit=document.querySelector('#auth-form button[type="submit"]');submit.innerHTML=mode==='signup'?'Criar conta <span>→</span>':'Entrar na conta <span>→</span>';document.querySelector('#auth-message').textContent=mode==='signup'?'Cadastro real indisponível sem um serviço de conta.':'';}
function authSubmit(form){const data=new FormData(form);const email=String(data.get('email')||'').trim().toLowerCase();const password=String(data.get('password')||'');if(email.endsWith('@demo.maison.test')){const account=DEMOS.find(d=>d.email===email&&d.password===password);if(account){loginDemo(account.id);return;}document.querySelector('#auth-message').textContent='Acesso de teste inválido. Use um dos perfis abaixo.';return;}document.querySelector('#auth-message').textContent='Login e cadastro reais precisam de um serviço de conta conectado. Use um perfil de demonstração para explorar a loja.';}
function loginDemo(id){const account=DEMOS.find(item=>item.id===id);if(!account)return;state.demoAccountId=id;state.branchId=account.branchId;if(!state.demoSeeded){const today=new Date().toISOString().slice(0,10);const makeItems=specs=>specs.map(([productId,quantity])=>({...PRODUCTS.find(p=>p.id===productId),quantity}));const specs=[{id:'DEMO1001',owner:'empresa',branch:'jardins',items:[['rainha-da-festa',120],['ouro-derretido',80],['combo-festa',6]]},{id:'DEMO1002',owner:'empresa',branch:'moema',items:[['croissant',50],['brownie',40]]},{id:'DEMO2001',owner:'pessoa',branch:'pinheiros',items:[['brownie',2],['bread',1]]},{id:'DEMO2002',owner:'pessoa',branch:'pinheiros',items:[['cheese',3]]}];state.orders.push(...specs.map(order=>{const items=makeItems(order.items);return {id:order.id,items,total:items.reduce((sum,item)=>sum+item.price*item.quantity,0),method:'pickup',date:today,time:'15:00',address:'',branchId:order.branch,demoOwner:order.owner,status:'scheduled',demoSeed:true,messages:[{text:'Pedido fictício para testes. Nenhuma encomenda real será enviada.',customer:false}]};}));state.demoSeeded=true;}persist();navigate('/testes');toast(`Bem-vindo, ${account.name}!`);}
function syncCheckout(){const form=document.querySelector('#checkout-form');if(!form)return;const method=form.querySelector('[name="method"]:checked')?.value||'pickup';const address=form.querySelector('.address-field');address.hidden=method!=='delivery';address.querySelector('input').required=method==='delivery';const fee=method==='delivery'?12:0;const feeLabel=document.querySelector('#delivery-fee');if(feeLabel)feeLabel.textContent=fee?money(fee):'Grátis';const totalLabel=document.querySelector('#order-total');if(totalLabel)totalLabel.textContent=money(subtotal()+fee-appliedCouponDiscount());const pickup=form.querySelector('.pickup-only');if(pickup){pickup.hidden=method!=='pickup';if(method!=='pickup'&&form.payment.value==='Pagar na retirada')form.payment.value='';}}
function appliedCouponDiscount(){const total=subtotal();const coupon=state.appliedCouponData;if(!state.appliedCoupon)return 0;if(!coupon)return state.appliedCoupon==='MAISON10'?total*.1:0;if(total<Number(coupon.valorMinimoPedido||0))return 0;const value=Number(coupon.valorDesconto||0);const discount=coupon.tipoDesconto==='PERCENTUAL'?total*value/100:value;return Math.max(0,Math.min(total,discount));}
async function applyCoupon(){const input=document.querySelector('[name="coupon"]');const message=document.querySelector('#coupon-message');const button=document.querySelector('[data-action="apply-coupon"]');if(!input||!message)return;const code=input.value.trim().toUpperCase();if(!code){message.textContent='Informe um código de cupom.';message.className='error-text';return;}if(button)button.disabled=true;message.textContent='Consultando cupom…';message.className='';try{const coupon=apiAdapter?.getCouponByCode?await apiAdapter.getCouponByCode(code):null;if(coupon){const now=Date.now();const starts=coupon.dataInicio?Date.parse(coupon.dataInicio):NaN;const expires=coupon.dataValidade?Date.parse(coupon.dataValidade):NaN;const valid=Boolean(coupon.ativo)&&(!Number.isFinite(starts)||now>=starts)&&(!Number.isFinite(expires)||now<=expires)&&Number(coupon.usosAtuais||0)<Number(coupon.limiteUsos??Infinity)&&subtotal()>=Number(coupon.valorMinimoPedido||0);if(!valid)throw new Error('Este cupom está expirado, esgotado ou não atende ao valor mínimo do pedido.');state.appliedCoupon=code;state.appliedCouponData=coupon;persist();message.textContent=`Cupom ${code} validado pela API Java. O pedido continua demonstrativo e não consome o cupom.`;message.className='success-text';}else if(code==='MAISON10'){state.appliedCoupon=code;state.appliedCouponData=null;persist();message.textContent='Cupom MAISON10 aplicado: 10% de desconto demonstrativo, salvo apenas neste navegador.';message.className='success-text';}else{state.appliedCoupon=null;state.appliedCouponData=null;message.textContent='Cupom não encontrado. A API Java não retornou este código.';message.className='error-text';}}catch(error){if(error.message?.startsWith('Este cupom')){state.appliedCoupon=null;state.appliedCouponData=null;message.textContent=error.message;message.className='error-text';}else if(code==='MAISON10'){state.appliedCoupon=code;state.appliedCouponData=null;persist();message.textContent='API Java indisponível; MAISON10 foi aplicado somente como cupom demonstrativo local.';message.className='success-text';}else{state.appliedCoupon=null;state.appliedCouponData=null;message.textContent='Não foi possível consultar a API Java. Tente novamente ou use MAISON10 (demonstração local).';message.className='error-text';}}finally{if(button)button.disabled=false;syncCheckout();}}
function checkout(form){const message=document.querySelector('#checkout-message');if(state.cart.some(i=>i.requiresPreparation&&!i.preparation)){message.textContent='Escolha o preparo de cada combo antes de finalizar.';message.className='form-message error-text';return;}const data=new FormData(form);const method=data.get('method');const fee=method==='delivery'?12:0;const discount=appliedCouponDiscount();const order={id:`M${Date.now().toString().slice(-6)}`,items:JSON.parse(JSON.stringify(state.cart)),total:subtotal()-discount+fee,method,date:String(data.get('date')).split('-').reverse().join('/'),time:data.get('time'),address:data.get('address')||'',branchId:state.branchId,demoOwner:state.demoAccountId,status:'scheduled',messages:[{text:'Olá! Recebemos seu pedido. Esta é uma conversa de demonstração — deixe sua mensagem por aqui.',customer:false}]};state.orders.unshift(order);state.cart=[];state.appliedCoupon=null;state.appliedCouponData=null;state.selectedOrder=order.id;persist();toast('Pedido registrado nesta demonstração. Nenhum pagamento foi processado.');navigate('/pedidos');}
function saveReview(){const order=(state.orders||[]).find(o=>o.id===(state.selectedOrder||(state.orders||[])[0]?.id));if(!order)return;const rating=state.reviewDraft?.rating||0;const text=document.querySelector('#review-text')?.value.trim()||'';if(!rating){toast('Escolha uma nota de 1 a 5 estrelas.');return;}order.review={rating,text};state.reviewDraft=null;persist();render();toast('Avaliação registrada nesta demonstração.');}
function sendOrderMessage(form){const order=state.orders.find(o=>o.id===state.selectedOrder)||state.orders[0];if(!order)return;const text=new FormData(form).get('message').trim();if(!text)return;order.messages.push({text,customer:true},{text:'Mensagem registrada na demonstração. Em uma loja real, nossa equipe responderia por aqui.',customer:false});persist();render();}
function newConversation(){const subject=window.prompt('Qual é o assunto da sua conversa?');if(!subject?.trim())return;const item={id:`c${Date.now()}`,subject:subject.trim().slice(0,100),messages:[{text:'Olá! Esta conversa foi criada em modo demonstrativo e não chega à equipe Maison.',own:false}]};state.conversations=[item,...(state.conversations||[])];state.selectedConversation=item.id;persist();render();}
function sendSupportMessage(form){const selected=(state.conversations||[]).find(c=>c.id===state.selectedConversation);const text=new FormData(form).get('message').trim();if(!selected||!text)return;selected.messages.push({text,own:true});persist();render();}
function filterStock(){const value=(document.querySelector('#stock-search')?.value||'').toLocaleLowerCase('pt-BR');document.querySelectorAll('[data-product-row]').forEach(row=>row.hidden=!row.dataset.productRow.includes(value));}
function filterConversations(){const value=(document.querySelector('#conversation-search')?.value||'').toLocaleLowerCase('pt-BR');document.querySelectorAll('.conversation-button').forEach(row=>row.hidden=!row.textContent.toLocaleLowerCase('pt-BR').includes(value));}
function saveDemoStock(){const id=document.querySelector('#demo-product').value;const status=document.querySelector('#demo-stock').value;const branchId=demosigned()?.branchId||state.branchId;state.stock={...(state.stock||{}),[id]:status};state.branchStock={...(state.branchStock||{}),[branchId]:{...(state.branchStock?.[branchId]||{}),[id]:status}};persist();document.querySelector('#demo-stock-message').textContent='Disponibilidade salva apenas neste navegador.';}
function storeTab(tab){document.querySelectorAll('.platform-tabs button').forEach(b=>{b.classList.toggle('selected',b.dataset.tab===tab);});document.querySelector('#stock-panel').hidden=tab!=='stock';document.querySelector('#campaigns-panel').hidden=tab!=='campaigns';}
function syncCakePreview(){const preview=document.querySelector('.cake-preview img');if(!preview)return;const dough=currentCake().dough;const image=dough==='Chocolate'?'bolo-1-andar-redondo-chocolate-brigadeiro-chocolate.webp':dough==='Baunilha'?'bolo-1-andar-redondo-baunilha-creme-de-baunilha-branca.webp':'cake-builder.webp';preview.src=`./assets/${image}`;}
function ensureBranchLocator(){const dialog=document.querySelector('#branch-dialog');if(!dialog||dialog.querySelector('[data-action="locate-branch"]'))return;const button=document.createElement('button');button.type='button';button.className='button button-outline branch-locate';button.dataset.action='locate-branch';button.textContent='Usar minha localização';const status=document.createElement('p');status.className='branch-location-status';status.id='branch-location-status';status.setAttribute('role','status');const options=dialog.querySelector('.branch-options');if(options){options.before(button,status);}}
function locateBranch(){const button=document.querySelector('[data-action="locate-branch"]');const status=document.querySelector('#branch-location-status');if(!navigator.geolocation){if(status)status.textContent='Seu navegador não oferece localização. Escolha uma loja abaixo.';return;}button.disabled=true;button.textContent='Localizando…';if(status)status.textContent='';navigator.geolocation.getCurrentPosition(position=>{const {latitude,longitude}=position.coords;const closest=[...BRANCHES].sort((a,b)=>((a.latitude-latitude)**2+(a.longitude-longitude)**2)-((b.latitude-latitude)**2+(b.longitude-longitude)**2))[0];state.branchId=closest.id;persist();document.querySelector('#branch-dialog')?.close();render();toast(`Loja ${closest.name} selecionada.`);},()=>{button.disabled=false;button.textContent='Usar minha localização';if(status)status.textContent='Não foi possível localizar você. Escolha sua loja manualmente.';},{timeout:10000});}
document.addEventListener('click',event=>{if(event.target.closest('[data-action="locate-branch"]'))locateBranch();});
document.addEventListener('change',event=>{if(event.target.id==='stock-branch'){state.stockBranch=event.target.value;persist();render();}if(event.target.matches('[data-stock-id]')){const branchId=document.querySelector('#stock-branch')?.value||'jardins';state.branchStock={...(state.branchStock||{}),[branchId]:{...(state.branchStock?.[branchId]||{}),[event.target.dataset.stockId]:event.target.value}};persist();}});
function rememberCheckoutField(event){const form=event.target.closest?.('#checkout-form');if(!form||!['method','date','time','address','payment'].includes(event.target.name))return;state.checkoutFields={...(state.checkoutFields||{}),[event.target.name]:event.target.value};persist();}
function restoreCheckoutFields(){const form=document.querySelector('#checkout-form');if(!form||!state.checkoutFields)return;for(const [name,value] of Object.entries(state.checkoutFields)){if(name==='method'){const radio=form.querySelector(`[name="method"][value="${value}"]`);if(radio)radio.checked=true;}else{const field=form.elements.namedItem(name);if(field)field.value=value;}}syncCheckout();}
